import 'package:freezed_annotation/freezed_annotation.dart';

import '../../../../core/domain/entities/master_plan.dart';
import '../../../nutrition/domain/entities/weekly_meal_plan.dart';

part 'weekly_workout_plan.freezed.dart';
part 'weekly_workout_plan.g.dart';

/// A complete 7-day workout plan generated by AI
@freezed
class WeeklyWorkoutPlan with _$WeeklyWorkoutPlan {
  const WeeklyWorkoutPlan._();

  const factory WeeklyWorkoutPlan({
    required String id,

    /// Start date of the week (Monday)
    required DateTime weekStartDate,

    /// When this plan was generated
    required DateTime generatedAt,

    /// Daily workout plans for each day of the week
    AiDailyWorkout? monday,
    AiDailyWorkout? tuesday,
    AiDailyWorkout? wednesday,
    AiDailyWorkout? thursday,
    AiDailyWorkout? friday,
    AiDailyWorkout? saturday,
    AiDailyWorkout? sunday,

    /// Total estimated calories burned for the week
    @Default(0) int totalEstimatedCaloriesBurn,

    /// Total workout minutes for the week
    @Default(0) int totalWorkoutMinutes,

    /// Number of workout days (non-rest days)
    @Default(0) int workoutDaysCount,

    /// Recovery score at the time of generation
    int? recoveryScoreAtGeneration,

    /// Strain score at the time of generation
    double? strainScoreAtGeneration,

    /// Is this an AI-generated plan?
    @Default(true) bool isAiGenerated,

    /// AI coaching note about the weekly plan
    String? coachingNote,

    /// Arabic coaching note
    String? coachingNoteAr,

    /// User's approval status
    @Default(PlanApprovalStatus.pending) PlanApprovalStatus approvalStatus,

    /// Linked meal plan ID for interconnection
    String? linkedMealPlanId,

    /// Fitness goals this plan targets
    @Default([]) List<String> fitnessGoals,

    /// Equipment required for the workouts
    @Default([]) List<String> equipmentRequired,
  }) = _WeeklyWorkoutPlan;

  factory WeeklyWorkoutPlan.fromJson(Map<String, dynamic> json) =>
      _$WeeklyWorkoutPlanFromJson(json);

  /// Get all daily workouts as a list
  List<AiDailyWorkout?> get dailyWorkouts => [
        monday,
        tuesday,
        wednesday,
        thursday,
        friday,
        saturday,
        sunday,
      ];

  /// Get daily workout by day index (0 = Monday, 6 = Sunday)
  AiDailyWorkout? getDayWorkout(int dayIndex) {
    switch (dayIndex) {
      case 0:
        return monday;
      case 1:
        return tuesday;
      case 2:
        return wednesday;
      case 3:
        return thursday;
      case 4:
        return friday;
      case 5:
        return saturday;
      case 6:
        return sunday;
      default:
        return null;
    }
  }

  /// Get workout days indices (0 = Monday)
  List<int> get workoutDayIndices {
    final indices = <int>[];
    for (var i = 0; i < 7; i++) {
      final workout = getDayWorkout(i);
      if (workout != null && !workout.isRestDay) {
        indices.add(i);
      }
    }
    return indices;
  }

  /// Get rest day indices (0 = Monday)
  List<int> get restDayIndices {
    final indices = <int>[];
    for (var i = 0; i < 7; i++) {
      final workout = getDayWorkout(i);
      if (workout == null || workout.isRestDay) {
        indices.add(i);
      }
    }
    return indices;
  }

  /// Get strength training day indices
  List<int> get strengthDayIndices {
    final indices = <int>[];
    for (var i = 0; i < 7; i++) {
      final workout = getDayWorkout(i);
      if (workout != null && workout.isStrengthTraining) {
        indices.add(i);
      }
    }
    return indices;
  }

  /// Get cardio day indices
  List<int> get cardioDayIndices {
    final indices = <int>[];
    for (var i = 0; i < 7; i++) {
      final workout = getDayWorkout(i);
      if (workout != null && workout.isCardio) {
        indices.add(i);
      }
    }
    return indices;
  }

  /// Get day name by index
  static String getDayName(int dayIndex, {bool arabic = false}) {
    const englishDays = [
      'Monday',
      'Tuesday',
      'Wednesday',
      'Thursday',
      'Friday',
      'Saturday',
      'Sunday'
    ];
    const arabicDays = [
      'الإثنين',
      'الثلاثاء',
      'الأربعاء',
      'الخميس',
      'الجمعة',
      'السبت',
      'الأحد'
    ];
    if (dayIndex < 0 || dayIndex > 6) return '';
    return arabic ? arabicDays[dayIndex] : englishDays[dayIndex];
  }

  /// Count of planned workout days
  int get plannedDaysCount =>
      dailyWorkouts.where((w) => w != null && !w.isRestDay).length;

  /// Is the plan complete (all 7 days have entries)?
  bool get isComplete => dailyWorkouts.every((w) => w != null);

  /// Average workout duration in minutes
  int get averageWorkoutDuration {
    final workouts = dailyWorkouts.where((w) => w != null && !w.isRestDay);
    if (workouts.isEmpty) return 0;
    return workouts.map((w) => w!.estimatedMinutes).reduce((a, b) => a + b) ~/
        workouts.length;
  }

  /// Get the date for a specific day index
  DateTime getDateForDay(int dayIndex) =>
      weekStartDate.add(Duration(days: dayIndex));

  /// Convert to WorkoutPlanSummary for coordination analysis
  WorkoutPlanSummary toSummary() {
    final dailyCalorieBurn = <int, int>{};
    for (var i = 0; i < 7; i++) {
      final workout = getDayWorkout(i);
      if (workout != null && !workout.isRestDay) {
        dailyCalorieBurn[i] = workout.estimatedCaloriesBurn;
      }
    }

    return WorkoutPlanSummary(
      planId: id,
      workoutDays: workoutDayIndices,
      strengthDays: strengthDayIndices,
      cardioDays: cardioDayIndices,
      restDays: restDayIndices,
      dailyCalorieBurn: dailyCalorieBurn,
      totalCalorieBurn: totalEstimatedCaloriesBurn,
      totalWorkoutMinutes: totalWorkoutMinutes,
      workoutDaysCount: workoutDaysCount,
    );
  }
}

/// A single day's workout in the weekly plan
@freezed
class AiDailyWorkout with _$AiDailyWorkout {
  const AiDailyWorkout._();

  const factory AiDailyWorkout({
    /// Reference to workout template ID (if using a template)
    String? workoutTemplateId,

    /// Name of the workout
    required String workoutName,

    /// Arabic name
    String? workoutNameAr,

    /// Category: strength, cardio, hiit, flexibility, recovery
    required String category,

    /// Estimated duration in minutes
    required int estimatedMinutes,

    /// Estimated calories burned
    required int estimatedCaloriesBurn,

    /// Suggested intensity (1-5)
    @Default(3) int suggestedIntensity,

    /// Best time of day to do this workout
    String? timeOfDay,

    /// Arabic time of day
    String? timeOfDayAr,

    /// Target muscle groups
    @Default([]) List<String> targetMuscleGroups,

    /// Equipment needed
    @Default([]) List<String> equipment,

    /// Whether this is a rest day
    @Default(false) bool isRestDay,

    /// Brief description of the workout
    String? description,

    /// Arabic description
    String? descriptionAr,

    /// Notes from the AI
    String? notes,

    /// List of exercises for this workout (NEW)
    @Default([]) List<AiWorkoutExercise> exercises,

    /// Warmup exercises (optional)
    @Default([]) List<AiWorkoutExercise> warmup,

    /// Cooldown exercises (optional)
    @Default([]) List<AiWorkoutExercise> cooldown,
  }) = _AiDailyWorkout;

  factory AiDailyWorkout.fromJson(Map<String, dynamic> json) =>
      _$AiDailyWorkoutFromJson(json);

  /// Is this a strength training workout?
  bool get isStrengthTraining => category.toLowerCase() == 'strength';

  /// Is this a cardio workout?
  bool get isCardio => category.toLowerCase() == 'cardio';

  /// Is this HIIT?
  bool get isHiit => category.toLowerCase() == 'hiit';

  /// Is this a flexibility/recovery workout?
  bool get isFlexibility =>
      category.toLowerCase() == 'flexibility' ||
      category.toLowerCase() == 'recovery';

  /// Create a rest day entry
  factory AiDailyWorkout.restDay() => const AiDailyWorkout(
        workoutName: 'Rest Day',
        workoutNameAr: 'يوم راحة',
        category: 'rest',
        estimatedMinutes: 0,
        estimatedCaloriesBurn: 0,
        suggestedIntensity: 0,
        isRestDay: true,
        description: 'Active recovery or complete rest',
        descriptionAr: 'راحة نشطة أو راحة كاملة',
        exercises: [],
        warmup: [],
        cooldown: [],
      );

  /// Total number of exercises (including warmup and cooldown)
  int get totalExerciseCount =>
      exercises.length + warmup.length + cooldown.length;

  /// Total sets for all main exercises
  int get totalSets =>
      exercises.fold(0, (sum, ex) => sum + ex.sets);

  /// Has exercises defined?
  bool get hasExercises => exercises.isNotEmpty;
}

/// An exercise in an AI-generated workout plan
@freezed
class AiWorkoutExercise with _$AiWorkoutExercise {
  const AiWorkoutExercise._();

  const factory AiWorkoutExercise({
    /// Exercise ID from the library (if matched)
    String? exerciseId,

    /// Exercise name
    required String name,

    /// Arabic name
    String? nameAr,

    /// Target muscle group
    String? muscleGroup,

    /// Number of sets
    required int sets,

    /// Target reps (for strength exercises)
    int? reps,

    /// Target duration in seconds (for timed exercises)
    int? durationSeconds,

    /// Rest between sets in seconds
    @Default(60) int restSeconds,

    /// Suggested weight (for strength exercises)
    String? suggestedWeight,

    /// Arabic weight suggestion
    String? suggestedWeightAr,

    /// Brief instruction
    String? instruction,

    /// Arabic instruction
    String? instructionAr,

    /// Order in the workout
    @Default(0) int order,

    /// Is this a superset with the next exercise?
    @Default(false) bool isSupersetWithNext,

    /// Equipment needed
    String? equipment,
  }) = _AiWorkoutExercise;

  factory AiWorkoutExercise.fromJson(Map<String, dynamic> json) =>
      _$AiWorkoutExerciseFromJson(json);

  /// Is this a timed exercise?
  bool get isTimed => durationSeconds != null && durationSeconds! > 0;

  /// Is this a rep-based exercise?
  bool get isRepBased => reps != null && reps! > 0;

  /// Display format for sets/reps (e.g., "4x10" or "3x30s")
  String get setsRepsDisplay {
    if (isTimed) {
      return '${sets}x${durationSeconds}s';
    } else if (isRepBased) {
      return '${sets}x$reps';
    }
    return '$sets sets';
  }
}

/// Context for requesting a weekly workout plan
@freezed
class WeeklyWorkoutPlanContext with _$WeeklyWorkoutPlanContext {
  const factory WeeklyWorkoutPlanContext({
    /// Week start date
    required DateTime weekStartDate,

    /// Recovery score
    int? recoveryScore,

    /// Strain score
    double? strainScore,

    /// Number of workout days desired (3-6)
    @Default(4) int targetWorkoutDays,

    /// Fitness goals
    @Default(['strength', 'fitness']) List<String> fitnessGoals,

    /// Available equipment
    @Default(['full_gym']) List<String> availableEquipment,

    /// Constraints (injuries, time limits, etc.)
    @Default([]) List<String> constraints,

    /// Preferred workout types
    @Default([]) List<String> preferredWorkoutTypes,

    /// Current meal plan (for coordination)
    MealPlanSummary? mealPlan,

    /// Language preference: 'ar' or 'en'
    @Default('ar') String language,
  }) = _WeeklyWorkoutPlanContext;

  factory WeeklyWorkoutPlanContext.fromJson(Map<String, dynamic> json) =>
      _$WeeklyWorkoutPlanContextFromJson(json);
}
